"""Repository of the "audit_log" table: reads and writes rows, and decides nothing."""

from __future__ import annotations

from typing import Any, Protocol

from sqlalchemy import select, tuple_
from sqlalchemy.ext.asyncio import AsyncSession

from app.entities.audit_log import AuditLog
from app.paging import CursorPage


class AuditLogRepository(Protocol):
    """Where audit_log rows are kept. Services depend only on this interface."""

    async def list(self, after: tuple[Any, ...] | None = None, limit: int = 50) -> CursorPage[AuditLog]:
        """At most `limit` rows after the key `after`, by primary key, and the key to read the next page from."""
        ...


class SqlAuditLogRepository:
    """Keeps audit_log rows in the database, through a AsyncSession. It never commits: the transaction belongs to whoever holds the session."""

    def __init__(self, session: AsyncSession) -> None:
        self._session = session

    async def list(self, after: tuple[Any, ...] | None = None, limit: int = 50) -> CursorPage[AuditLog]:
        """At most `limit` rows after the key `after`, by primary key, and the key to read the next page from."""
        query = select(AuditLog)
        if after is not None:
            query = query.where(tuple_(AuditLog.at, AuditLog.message) > tuple_(*after))
        rows = list((await self._session.scalars(query.order_by(AuditLog.at, AuditLog.message).limit(limit + 1))).all())
        more = len(rows) > limit
        rows = rows[:limit]
        last = (rows[-1].at, rows[-1].message,) if more else None
        return CursorPage(items=rows, next=last)


class MemoryAuditLogRepository:
    """Keeps audit_log rows in memory, for tests and for trying the services without a database."""

    def __init__(self) -> None:
        self._rows: dict[tuple[Any, ...], AuditLog] = {}

    @staticmethod
    def _key(row: AuditLog) -> tuple[Any, ...]:
        return (row.at, row.message,)

    async def list(self, after: tuple[Any, ...] | None = None, limit: int = 50) -> CursorPage[AuditLog]:
        """At most `limit` rows after the key `after`, by primary key, and the key to read the next page from."""
        rows = [row for row in [row for row in sorted(self._rows.values(), key=self._key) if True] if after is None or self._key(row) > tuple(after)]
        more = len(rows) > limit
        rows = rows[:limit]
        return CursorPage(items=rows, next=self._key(rows[-1]) if more else None)

